import type { ReactNode } from "react";

/**
 * Catalogue des skins de buzzer (refonte Arcade) : 7 familles, dessins en
 * aplats + motifs cernés de noir (SVG, viewBox 0 0 100 100). Maquettes :
 * canvas "Blindtest — Refonte Arcade", page Profil v2, planche "Skins du
 * buzzer".
 *
 * IDENTIFIANTS CONSERVÉS : les familles Arcade, Fête et Fiertés reprennent
 * les clés de Jungle (nature_*), Cosmos (cosmique_*) et Slay (slay_*) — un
 * skin déjà équipé reste équipé, sous sa nouvelle apparence.
 *
 * DÉBLOCAGE : calculé à la volée à partir de l'XP et des badges du compte
 * (isCosmeticUnlocked, côté navigateur ET côté serveur dans
 * api/player-account/equip-cosmetic). Pour changer une règle, il suffit de
 * modifier `unlock` / `unlockHint` ci-dessous, sans migration.
 * (player_cosmetics ne sert plus qu'à mémoriser le skin équipé.)
 */

export type CosmeticCategory = "uni" | "musique" | "motifs" | "arcade" | "fete" | "gourmand" | "fiertes";

export type CosmeticUnlockCondition =
  | { type: "always" }
  | { type: "first_badge_tier"; tier: "bronze" | "argent" | "or" } // n'importe quel badge à ce palier
  | { type: "level"; level: number }
  | { type: "level_and_badge_or"; level: number; badgeKey: string }; // niveau + un badge précis en or

export type CosmeticDefinition = {
  key: string;
  category: CosmeticCategory;
  label: string;
  /** Couleur de fond du dessin. */
  bg: string;
  /** Dessin SVG (contenu d'un viewBox 0 0 100 100), null pour un aplat. */
  art: string | null;
  /** Fond CSS du buzzer (aplat ou dessin en data URI). */
  swatch: string;
  /** Couleur représentative (anneaux, textes...). */
  accentColor: string;
  /** Contraste du texte "BUZZ" posé directement sur le skin (aplats). */
  textOn: "dark" | "light";
  /** Vestige de l'ancien catalogue (icône en filigrane) : plus utilisé. */
  icon?: (props: { size: number }) => ReactNode;
  unlock: CosmeticUnlockCondition;
  unlockHint: string;
};

type RawCosmetic = Omit<CosmeticDefinition, "swatch">;

