function swatchOf(c: RawCosmetic): string {
  if (!c.art) return c.bg;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" preserveAspectRatio="xMidYMid slice">${c.art}</svg>`;
  return `url("data:image/svg+xml,${encodeURIComponent(svg)}") center / cover no-repeat, ${c.bg}`;
}

export const COSMETIC_DEFINITIONS: CosmeticDefinition[] = RAW.map((c) => ({ ...c, swatch: swatchOf(c) }));

export const COSMETIC_BY_KEY: Record<string, CosmeticDefinition> = Object.fromEntries(
  COSMETIC_DEFINITIONS.map((c) => [c.key, c])
);

export const DEFAULT_COSMETIC_KEY = "uni_sage";

export const COSMETIC_CATEGORIES: CosmeticCategory[] = ["uni", "musique", "motifs", "arcade", "fete", "gourmand", "fiertes"];

export const COSMETIC_CATEGORY_LABEL: Record<CosmeticCategory, string> = { uni: "Couleurs", musique: "Musique", motifs: "Motifs", arcade: "Arcade", fete: "Fête", gourmand: "Gourmand", fiertes: "Fiertés" };

const TIER_RANK = { none: 0, bronze: 1, argent: 2, or: 3 } as const;

export type CosmeticUnlockContext = {
  xp: number;
  badges: Record<string, { tier: "none" | "bronze" | "argent" | "or" }>;
};

/** Règle de déblocage (même calcul côté navigateur et côté serveur). */
export function isCosmeticUnlocked(def: CosmeticDefinition, ctx: CosmeticUnlockContext): boolean {
  const u = def.unlock;
  const level = Math.floor(Math.max(ctx.xp, 0) / 100) + 1;
  if (u.type === "always") return true;
  if (u.type === "level") return level >= u.level;
  if (u.type === "first_badge_tier") {
    return Object.values(ctx.badges).some((b) => TIER_RANK[b.tier] >= TIER_RANK[u.tier]);
  }
  return level >= u.level && ctx.badges[u.badgeKey]?.tier === "or";
}
